         public static void MoveTo<T>(this T ctrl, Point pos, int roundStep) {            MoveTo(                ctrl, new Point(                (int)Math.Round((double)pos.X / roundStep) * roundStep,                (int)Math.Round((double)pos.Y / roundStep) * roundStep           ));        }        public static void MoveTo<T>(this T ctrl, Point pos) {            if (ctrl.HasProperty("Location")) ctrl.SetProperty("Location", pos);        }        public static bool HasProperty(this object obj, string propertyName) {            return obj.GetType().GetProperty(propertyName) != null;        }        public static void SetProperty<T>(this object obj, string propertyName, T value) {            obj.GetType().SetProperty(propertyName, value);        }namespace NetComponents.extensions {    public static class ObjectExtensions {        public static bool HasProperty(this object obj, string propertyName) {            return obj.GetType().GetProperty(propertyName) != null;        }        public static void SetProperty<T>(this object obj, string propertyName, T value) {            obj.GetType().SetProperty(propertyName, value);        }    }}